module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    parameter NAN = 32'h7FC00000;
    parameter INF = 32'h7F800000;
    always @(posedge clk or posedge rst) begin
        if(rst) begin
            counter <= 3'd0;
        end else begin
            case(counter)
                3'd0: begin
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_sign <= a[31];
                    b_sign <= b[31];
                    counter <= 3'd1;
                end

                3'd1: begin
                    if((a == NAN || b == NAN)) begin
                        z <= NAN;
                        counter <= 3'd2;
                    end else if((a == INF && b != 0) || (b == INF && a != 0)) begin
                        z <= INF;
                        counter <= 3'd2;
                    end else if(a == 0 || b == 0) begin
                        z <= 0;
                        counter <= 3'd2;
                    end else begin
                        if(a_exponent == 0) begin
                            a_mantissa <= {1'b0, a[22:0]};
                            a_exponent <= 10'd1;
                        end
                        if(b_exponent == 0) begin
                            b_mantissa <= {1'b0, b[22:0]};
                            b_exponent <= 10'd1;
                        end
                        counter <= 3'd2;
                    end
                end

                3'd2: begin
                    product <= a_mantissa * b_mantissa;
                    z_exponent <= a_exponent + b_exponent - 10'd127;
                    z_sign <= a_sign ^ b_sign;
                    counter <= 3'd3;
                end

                3'd3: begin
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];

                    if(product[49]) begin
                        z_mantissa <= product[48:24] >> 1;
                        z_exponent <= z_exponent + 1;
                    end else begin
                        z_mantissa <= product[47:23];
                    end

                    if(z_exponent >= 10'd255) begin
                        z <= {z_sign, 8'hFF, 23'h0};
                    end else if(z_exponent <= 0) begin
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'd4;
                end

                default: begin
                    counter <= 3'd0;
                end
            endcase
        end
    end
endmodule
